def course_guide(n):
    row = GUIDES.get(19 if n in (20, 21) else n)
    if not row:
        return {'n': n, 'slides': []}
    title, idea, method, question, solution, answer, mistake = row
    text = lambda h, body: {'t': 'text', 'h': h, 'html': '<p>' + escape(body) + '</p>'}
    return {'n': n, 'label': title, 'format': 'Архивное задание · нет в КИМ-2027' if n in (28,) else 'Краткий разбор · КИМ ЕГЭ-2027', 'slides': [
        text(title, idea),
        {'t': 'text', 'h': 'План решения', 'html': '<ol>' + ''.join('<li>' + escape(x.strip()) + '</li>' for x in method.split(';')) + '</ol>'},
        {'t': 'solve', 'h': 'Сначала попробуй сам', 'ch': 'Учебный пример', 'cond': '<p>' + escape(question) + '</p>',
         'sol': '<p>' + escape(solution) + '</p>', 'ans': answer},
        text('Проверь себя перед сдачей', mistake),
    ]}
